        run,
        artifact.digest,
        source_digest,
        &workflow,
        Box::from([(SlotIdx::new(0), SlotValue::I64(value))]),
    )?;
    Ok(RunSubmission::new(
        WorkflowSourceRecord {
            digest: source_digest,
            source,
        },
        artifact,
        inputs,
        RunHeaderRecord {
            run,
            workflow_id: WorkflowId::new(0),
            compiled_digest: workflow.digest(),
            status: 0,
            accepted_at_ms: 1000,
        },
    )?)
}

